True def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not marks:
        return [row[:] for row in grid]
    projections = {
        "row": lambda r, c: r,
        "col": lambda r, c: c,
        "sum": lambda r, c: r + c,
        "diff": lambda r, c: c - r,
    }
    # Clues form full parallel stripes in one of these orientations.
    name = min(projections, key=lambda n: len({projections[n](r, c) for r, c, _ in marks}))
    f = projections[name]
    stripes = {f(r, c) for r, c, _ in marks}
    period = len(stripes)
    pattern = {}
    for r, c, color in marks:
        pattern[f(r, c) % period] = color
    return [[pattern[(f(r, c) % period)] for c in range(w)] for r in range(h)]
